function majorityElement(nums) {
  const count = {};

  for (const num of nums) {
    count[num] = (count[num] || 0) + 1;
  }

  for (const num in count) {
    if (count[num] > nums.length / 2) {
      return Number(num);
    }
  }
  return -1;
}

// Or in one pass with Boyer-Moore:
function majorityElementOptimized(nums) {
  let candidate = null;
  let count = 0;

  for (const num of nums) {
    if (count === 0) candidate = num;
    count += num === candidate ? 1 : -1;
  }
  return candidate;
}

function isAnagram(s, t) {
  if (s.length !== t.length) return false;

  const count = {};
  for (const char of s) {
    count[char] = (count[char] || 0) + 1;
  }

  for (const char of t) {
    if (!count[char]) return false;
    count[char]--;
  }

  return true;
}

// One-liner using Map:
function isAnagramMap(s, t) {
  if (s.length !== t.length) return false;
  const count = new Map();
  for (const c of s) count.set(c, (count.get(c) || 0) + 1);
  for (const c of t) {
    if (!count.has(c)) return false;
    count.set(c, count.get(c) - 1);
  }
  return true;
}

function fibMemo(n, memo = {}) {
  if (n in memo) return memo[n];
  if (n <= 1) return n;

  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}

// Iterative DP with cache:
function fibIterative(n) {
  if (n <= 1) return n;
  const dp = [0, 1];

  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

// Space-optimized:
function fibOptimized(n) {
  if (n <= 1) return n;
  let prev = 0, curr = 1;
  for (let i = 2; i <= n; i++) {
    [prev, curr] = [curr, prev + curr];
  }
  return curr;
}

class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map(); // maintains insertion order
  }

  get(key) {
    if (!this.cache.has(key)) return -1;

    // Move to end (most recently used)
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  put(key, value) {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.capacity) {
      // Map.keys() returns iterator in insertion order
      const lru = this.cache.keys().next().value;
      this.cache.delete(lru);
    }
    this.cache.set(key, value);
  }
}

function groupAnagrams(strs) {
  const groups = {};

  for (const str of strs) {
    const key = str.split('').sort().join('');
    if (!groups[key]) groups[key] = [];
    groups[key].push(str);
  }

  return Object.values(groups);
}

// Optimized with character count key:
function groupAnagramsOptimized(strs) {
  const groups = {};

  for (const str of strs) {
    const count = new Array(26).fill(0);
    for (const c of str) count[c.charCodeAt(0) - 97]++;
    const key = count.join('#');
    if (!groups[key]) groups[key] = [];
    groups[key].push(str);
  }

  return Object.values(groups);
}

function twoSum(nums, target) {
  const seen = new Map();

  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];

    if (seen.has(complement)) {
      return [seen.get(complement), i];
    }

    seen.set(nums[i], i);
  }
  return [];
}

// Object variant:
function twoSumObj(nums, target) {
  const map = {};

  for (let i = 0; i < nums.length; i++) {
    const comp = target - nums[i];
    if (map[comp] !== undefined) return [map[comp], i];
    map[nums[i]] = i;
  }
  return [];
}

function hasDuplicate(nums) {
  const seen = new Set();

  for (const num of nums) {
    if (seen.has(num)) return true;
    seen.add(num);
  }
  return false;
}

function removeDuplicates(nums) {
  return [...new Set(nums)];
}

// Intersection of two arrays:
function intersection(nums1, nums2) {
  const set1 = new Set(nums1);
  const result = [];

  for (const num of nums2) {
    if (set1.has(num)) {
      result.push(num);
      set1.delete(num); // avoid duplicates in result
    }
  }
  return result;
}

function isHappy(n) {
  const seen = new Set();

  while (n !== 1) {
    if (seen.has(n)) return false; // cycle detected
    seen.add(n);

    let sum = 0;
    while (n > 0) {
      const digit = n % 10;
      sum += digit * digit;
      n = Math.floor(n / 10);
    }
    n = sum;
  }

  return true;
}

// Alternative: Floyd's Cycle Detection (O(1) space)
function isHappyFloyd(n) {
  function sumDigits(x) {
    let sum = 0;
    while (x > 0) {
      const d = x % 10;
      sum += d * d;
      x = Math.floor(x / 10);
    }
    return sum;
  }

  let slow = n, fast = sumDigits(n);
  while (fast !== 1 && slow !== fast) {
    slow = sumDigits(slow);
    fast = sumDigits(sumDigits(fast));
  }
  return fast === 1;
}
